-- DriveSphere: Oracle 19c+ schema
CREATE TABLE branches (branch_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(100) NOT NULL UNIQUE);
CREATE TABLE courses (course_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(100) NOT NULL, required_sessions NUMBER(3) NOT NULL CHECK(required_sessions>0), fee NUMBER(10,2) NOT NULL CHECK(fee>=0));
CREATE TABLE learners (learner_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id NUMBER NOT NULL REFERENCES branches, course_id NUMBER NOT NULL REFERENCES courses, full_name VARCHAR2(120) NOT NULL, email VARCHAR2(180) UNIQUE, enrolled_on DATE DEFAULT SYSDATE NOT NULL);
CREATE TABLE instructors (instructor_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id NUMBER NOT NULL REFERENCES branches, full_name VARCHAR2(120) NOT NULL, active CHAR(1) DEFAULT 'Y' CHECK(active IN ('Y','N')));
CREATE TABLE vehicles (vehicle_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id NUMBER NOT NULL REFERENCES branches, registration_no VARCHAR2(20) NOT NULL UNIQUE, status VARCHAR2(20) DEFAULT 'READY' CHECK(status IN ('READY','MAINTENANCE','INACTIVE')));
CREATE TABLE slots (slot_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id NUMBER NOT NULL REFERENCES branches, instructor_id NUMBER NOT NULL REFERENCES instructors, vehicle_id NUMBER NOT NULL REFERENCES vehicles, starts_at TIMESTAMP NOT NULL, ends_at TIMESTAMP NOT NULL, CONSTRAINT ck_slot_time CHECK(ends_at>starts_at));
CREATE TABLE sessions (session_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slot_id NUMBER NOT NULL UNIQUE REFERENCES slots, learner_id NUMBER NOT NULL REFERENCES learners, status VARCHAR2(20) DEFAULT 'BOOKED' NOT NULL CHECK(status IN ('BOOKED','COMPLETED','CANCELLED','NO_SHOW')));
CREATE TABLE attendance (session_id NUMBER PRIMARY KEY REFERENCES sessions, present CHAR(1) NOT NULL CHECK(present IN ('Y','N')), marked_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE llr_applications (llr_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, learner_id NUMBER NOT NULL REFERENCES learners, application_no VARCHAR2(60) UNIQUE, status VARCHAR2(20) NOT NULL CHECK(status IN ('DRAFT','SUBMITTED','APPROVED','REJECTED')), issued_on DATE, expires_on DATE, CHECK(expires_on IS NULL OR issued_on IS NULL OR expires_on>issued_on));
CREATE TABLE test_bookings (test_booking_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, learner_id NUMBER NOT NULL REFERENCES learners, test_date DATE NOT NULL, attempt_no NUMBER(3) NOT NULL CHECK(attempt_no>0), status VARCHAR2(20) DEFAULT 'SCHEDULED' NOT NULL CHECK(status IN ('SCHEDULED','CANCELLED','COMPLETED')), UNIQUE(learner_id,attempt_no));
CREATE TABLE test_results (test_booking_id NUMBER PRIMARY KEY REFERENCES test_bookings, outcome VARCHAR2(10) NOT NULL CHECK(outcome IN ('PASS','FAIL')), recorded_on DATE DEFAULT SYSDATE NOT NULL);
CREATE TABLE payments (payment_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, learner_id NUMBER NOT NULL REFERENCES learners, amount NUMBER(10,2) NOT NULL CHECK(amount>0), paid_on DATE DEFAULT SYSDATE NOT NULL, reference_no VARCHAR2(80) UNIQUE);
CREATE INDEX ix_slots_instructor_time ON slots(instructor_id,starts_at,ends_at);
CREATE INDEX ix_slots_vehicle_time ON slots(vehicle_id,starts_at,ends_at);
CREATE INDEX ix_sessions_learner ON sessions(learner_id,status);
